CREATE TABLE "connector_catalog" (
    "id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
    "code" varchar(100) NOT NULL UNIQUE,
    "name" varchar(100) NOT NULL,
    "connector_type" varchar(50) NOT NULL,
    "category" varchar(100) NOT NULL,
    "description" text,
    "adapter_key" varchar(100) NOT NULL,
    "config_schema" jsonb NOT NULL,
    "is_enabled" boolean NOT NULL,
    "created_at" timestamp with time zone DEFAULT now() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "connector_catalog_connector_type_connector_types_code_fk"
        FOREIGN KEY ("connector_type") REFERENCES "connector_types" ("code") ON DELETE RESTRICT ON UPDATE CASCADE
);
--> statement-breakpoint
CREATE INDEX "connector_catalog_type_category_enabled_idx" ON "connector_catalog" ("connector_type", "category", "is_enabled");
--> statement-breakpoint
ALTER TABLE "connections" ADD COLUMN "catalog_id" uuid;
--> statement-breakpoint
ALTER TABLE "connections" ADD COLUMN "verified_at" timestamp with time zone;
--> statement-breakpoint
ALTER TABLE "connections" ADD COLUMN "verification_metadata" jsonb;
--> statement-breakpoint
ALTER TABLE "connections" ADD CONSTRAINT "connections_catalog_id_connector_catalog_id_fk"
    FOREIGN KEY ("catalog_id") REFERENCES "connector_catalog" ("id") ON DELETE RESTRICT;
